import React from 'react';
import { Grid, Stack, Typography, Box, Chip } from '@mui/material';
import TrendingUpRoundedIcon from '@mui/icons-material/TrendingUpRounded';
import CheckCircleRoundedIcon from '@mui/icons-material/CheckCircleRounded';
import ErrorOutlineRoundedIcon from '@mui/icons-material/ErrorOutlineRounded';
import BugReportRoundedIcon from '@mui/icons-material/BugReportRounded';
import FlashOnRoundedIcon from '@mui/icons-material/FlashOnRounded';
import SpeedRoundedIcon from '@mui/icons-material/SpeedRounded';
import KpiCard from '../components/KpiCard';
import AnalyticsCharts from '../components/AnalyticsCharts';
import HeatmapPanel from '../components/HeatmapPanel';
import AiInsightsCard from '../components/AiInsightsCard';

function DashboardPage() {
  const kpis = [
    { title: 'Total Test Executions', value: '184', change: '+12.8% vs last week', icon: <TrendingUpRoundedIcon />, accent: '#2563EB' },
    { title: 'Pass Rate', value: '92%', change: '+3.2% stable', icon: <CheckCircleRoundedIcon />, accent: '#22C55E' },
    { title: 'Failure Rate', value: '8%', change: '-1.4% improved', icon: <ErrorOutlineRoundedIcon />, accent: '#EF4444' },
    { title: 'Flaky Tests', value: '14', change: '3 critical', icon: <BugReportRoundedIcon />, accent: '#F59E0B' },
    { title: 'Critical Hotspots', value: '6', change: '2 new this week', icon: <FlashOnRoundedIcon />, accent: '#0EA5E9' },
    { title: 'Quality Score', value: '88/100', change: 'Excellent', icon: <SpeedRoundedIcon />, accent: '#22C55E' },
  ];

  return (
    <Box>
      <Stack direction={{ xs: 'column', md: 'row' }} justifyContent="space-between" alignItems={{ xs: 'flex-start', md: 'center' }} spacing={2} mb={3}>
        <Box>
          <Typography variant="h4" fontWeight={700}>Executive Quality Command Center</Typography>
          <Typography variant="body1" color="text.secondary">AI-driven reliability insights for your CI/CD ecosystem.</Typography>
        </Box>
        <Chip label="Updated 2 min ago" color="success" />
      </Stack>
      <Grid container spacing={2.5} mb={3}>
        {kpis.map((kpi) => (
          <Grid item xs={12} sm={6} md={4} lg={2} key={kpi.title}>
            <KpiCard {...kpi} />
          </Grid>
        ))}
      </Grid>
      <Grid container spacing={3}>
        <Grid item xs={12} lg={8}>
          <AnalyticsCharts />
        </Grid>
        <Grid item xs={12} lg={4}>
          <Stack spacing={3}>
            <AiInsightsCard />
            <HeatmapPanel />
          </Stack>
        </Grid>
      </Grid>
    </Box>
  );
}

export default DashboardPage;
